export function timeAgo(fecha) {
	if (!(fecha instanceof Date)) {
		fecha = new Date(fecha);
	}

	const ahora = new Date();
	const segundos = Math.floor((ahora - fecha) / 1000);

	if (segundos < 0) return 'dentro de un momento';

	const intervalos = [
		{ segundos: 31536000, singular: 'un año', plural: '%d años' },
		{ segundos: 2592000,  singular: 'un mes', plural: '%d meses' },
		{ segundos: 86400,    singular: 'un día', plural: '%d días' },
		{ segundos: 3600,     singular: 'una hora', plural: '%d horas' },
		{ segundos: 60,       singular: 'un minuto', plural: 'unos %d minutos' }
	];

	if (segundos < 45) {
		return 'hace menos de un minuto';
	}

	for (const i of intervalos) {
		const valor = Math.floor(segundos / i.segundos);
		if (valor >= 1) {
			return valor === 1 ? `hace ${i.singular}` : `hace ${i.plural.replace('%d', valor)}`;
		}
	}

	return 'hace un momento';
}